fn rjust(orig: Vec<char>, width: u8, fillchar: char) -> Vec<char> {
    let orig_len = orig.len() as u8; // Get the length of the original vector

    if orig_len >= width {
        // If the original length is greater than or equal to the target width, return it unchanged
        return orig;
    }

    // Create a new vector with the target width, filled with the fill character
    let mut res = vec![fillchar; width as usize];

    // Copy the original characters to the end of the new vector
    let start_index = (width - orig_len) as usize; // Calculate the starting index for the original characters
    res[start_index..(start_index + orig_len as usize)].copy_from_slice(&orig);

    res // Return the new vector
}